-- Generated by `fastauth generate`. Review it before applying.

CREATE TABLE "user" (
    "id" text NOT NULL CONSTRAINT "user_pkey" PRIMARY KEY,
    "email" text NOT NULL CONSTRAINT "user_email_key" UNIQUE,
    "email_verified" boolean NOT NULL DEFAULT false,
    "name" text NOT NULL,
    "image" text,
    "created_at" timestamptz NOT NULL DEFAULT now(),
    "updated_at" timestamptz NOT NULL DEFAULT now(),
    "two_factor_enabled" boolean NOT NULL DEFAULT false,
    "role" text,
    "banned" boolean NOT NULL DEFAULT false,
    "ban_reason" text,
    "ban_expires" timestamptz
);

CREATE TABLE "session" (
    "id" text NOT NULL CONSTRAINT "session_pkey" PRIMARY KEY,
    "token_hash" bytea NOT NULL CONSTRAINT "session_token_hash_key" UNIQUE,
    "user_id" text NOT NULL REFERENCES "user" ("id") ON DELETE CASCADE,
    "expires_at" timestamptz NOT NULL,
    "ip_address" text,
    "user_agent" text,
    "created_at" timestamptz NOT NULL DEFAULT now(),
    "updated_at" timestamptz NOT NULL DEFAULT now(),
    "active_organization_id" text,
    "impersonated_by" text
);

CREATE INDEX "idx_session_user_id" ON "session" ("user_id");

CREATE TABLE "account" (
    "id" text NOT NULL CONSTRAINT "account_pkey" PRIMARY KEY,
    "user_id" text NOT NULL REFERENCES "user" ("id") ON DELETE CASCADE,
    "provider_id" text NOT NULL,
    "account_id" text NOT NULL,
    "password_hash" text,
    "access_token" bytea,
    "refresh_token" bytea,
    "id_token" text,
    "access_token_expires_at" timestamptz,
    "refresh_token_expires_at" timestamptz,
    "scope" text,
    "created_at" timestamptz NOT NULL DEFAULT now(),
    "updated_at" timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX "idx_account_user_id" ON "account" ("user_id");

CREATE INDEX "idx_account_account_id" ON "account" ("account_id");

CREATE TABLE "verification" (
    "id" text NOT NULL CONSTRAINT "verification_pkey" PRIMARY KEY,
    "identifier" text NOT NULL,
    "value_hash" bytea NOT NULL CONSTRAINT "verification_value_hash_key" UNIQUE,
    "data" text,
    "expires_at" timestamptz NOT NULL,
    "created_at" timestamptz NOT NULL DEFAULT now(),
    "updated_at" timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX "idx_verification_identifier" ON "verification" ("identifier");

CREATE TABLE "two_factor" (
    "id" text NOT NULL CONSTRAINT "two_factor_pkey" PRIMARY KEY,
    "user_id" text NOT NULL REFERENCES "user" ("id") ON DELETE CASCADE,
    "secret" bytea NOT NULL,
    "backup_codes" bytea NOT NULL,
    "last_used_step" bigint
);

CREATE INDEX "idx_two_factor_user_id" ON "two_factor" ("user_id");

CREATE TABLE "passkey" (
    "id" text NOT NULL CONSTRAINT "passkey_pkey" PRIMARY KEY,
    "name" text,
    "public_key" text NOT NULL,
    "user_id" text NOT NULL REFERENCES "user" ("id") ON DELETE CASCADE,
    "credential_id" text NOT NULL CONSTRAINT "passkey_credential_id_key" UNIQUE,
    "counter" bigint NOT NULL,
    "device_type" text NOT NULL,
    "backed_up" boolean NOT NULL,
    "transports" text,
    "created_at" timestamptz NOT NULL DEFAULT now(),
    "aaguid" text
);

CREATE INDEX "idx_passkey_user_id" ON "passkey" ("user_id");

CREATE TABLE "organization" (
    "id" text NOT NULL CONSTRAINT "organization_pkey" PRIMARY KEY,
    "name" text NOT NULL,
    "slug" text NOT NULL CONSTRAINT "organization_slug_key" UNIQUE,
    "logo" text,
    "metadata" jsonb,
    "created_at" timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE "member" (
    "id" text NOT NULL CONSTRAINT "member_pkey" PRIMARY KEY,
    "organization_id" text NOT NULL REFERENCES "organization" ("id") ON DELETE CASCADE,
    "user_id" text NOT NULL REFERENCES "user" ("id") ON DELETE CASCADE,
    "role" text NOT NULL DEFAULT 'member',
    "created_at" timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX "idx_member_organization_id" ON "member" ("organization_id");

CREATE INDEX "idx_member_user_id" ON "member" ("user_id");

CREATE TABLE "invitation" (
    "id" text NOT NULL CONSTRAINT "invitation_pkey" PRIMARY KEY,
    "organization_id" text NOT NULL REFERENCES "organization" ("id") ON DELETE CASCADE,
    "email" text NOT NULL,
    "role" text NOT NULL,
    "status" text NOT NULL DEFAULT 'pending',
    "inviter_id" text NOT NULL REFERENCES "user" ("id") ON DELETE CASCADE,
    "expires_at" timestamptz NOT NULL,
    "created_at" timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX "idx_invitation_organization_id" ON "invitation" ("organization_id");

CREATE INDEX "idx_invitation_email" ON "invitation" ("email");

CREATE TABLE "apikey" (
    "id" text NOT NULL CONSTRAINT "apikey_pkey" PRIMARY KEY,
    "name" text,
    "start" text,
    "prefix" text,
    "key_hash" bytea NOT NULL CONSTRAINT "apikey_key_hash_key" UNIQUE,
    "user_id" text NOT NULL REFERENCES "user" ("id") ON DELETE CASCADE,
    "enabled" boolean NOT NULL DEFAULT true,
    "expires_at" timestamptz,
    "rate_limit_enabled" boolean NOT NULL DEFAULT true,
    "rate_limit_time_window" bigint,
    "rate_limit_max" bigint,
    "request_count" bigint NOT NULL DEFAULT 0,
    "last_request" timestamptz,
    "remaining" bigint,
    "refill_amount" bigint,
    "refill_interval" bigint,
    "last_refill_at" timestamptz,
    "permissions" jsonb,
    "metadata" jsonb,
    "created_at" timestamptz NOT NULL DEFAULT now(),
    "updated_at" timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX "idx_apikey_user_id" ON "apikey" ("user_id");
